import re
# Enum\USBSTOR: model + serial per device
dev = {}
cur = None
for line in open('usbstore.txt'):
    line = line.rstrip('\n')
    m = re.match(r'USBSTOR\\Disk&Ven_\S+', line)
    if m:
        cur = line.strip(); dev[cur] = {}
    elif cur and line.strip().startswith('S/N:'):
        dev[cur]['serial'] = line.split(':', 1)[1].strip()
# MountedDevices: volume serial -> drive letter
vol = {}
for line in open('mounted_devices.txt'):
    m = re.match(r'\\DosDevices\\([A-Z]): -> Serial: (\S+)', line.strip())
    if m:
        vol[m.group(2)] = m.group(1)
# LNK: which file lives on which volume serial
for row in open('lnk.csv').read().splitlines()[1:]:
    target, vsn, drive = row.split(',')
    if drive != 'Removable':
        continue
    if vsn in vol:
        # map VSN 4C53-0001 back to the USBSTOR serial 4C530001120523116345
        norm = vsn.replace('-', '')
        for k, v in dev.items():
            if v['serial'].startswith(norm):
                print('file           :', target)
                print('volume serial  :', vsn, '-> drive', vol[vsn])
                print('device         :', k)
                print('device serial  :', v['serial'])
                print('flag: nto{' + v['serial'] + '}')
